(function(r,f){const m=f();if(typeof module==='object')module.exports=m;else r.Model=m})(globalThis,()=>{async function totp(secret,{time=Date.now()/1000,period=30,digits=6,algorithm='SHA-1'}={},provider=globalThis.crypto){if(!(secret instanceof Uint8Array)||secret.length<16||secret.length>128||!Number.isFinite(time)||time<0||!Number.isSafeInteger(Math.floor(time))||![30,60].includes(period)||![6,8].includes(digits)||!['SHA-1','SHA-256','SHA-512'].includes(algorithm)||!provider?.subtle)throw Error('Invalid TOTP parameters or unavailable cryptography');let c=BigInt(Math.floor(time/period));const msg=new Uint8Array(8);for(let i=7;i>=0;i--){msg[i]=Number(c&255n);c>>=8n}if(c)throw Error('Counter overflow');const key=await provider.subtle.importKey('raw',secret,{name:'HMAC',hash:algorithm},false,['sign']);const hash=new Uint8Array(await provider.subtle.sign('HMAC',key,msg));const o=hash[hash.length-1]&15;const n=((hash[o]&127)*16777216)+(hash[o+1]<<16)+(hash[o+2]<<8)+hash[o+3];hash.fill(0);msg.fill(0);return String(n%(10**digits)).padStart(digits,'0')}function capability(x){if(!x||x.version!==1||x.encrypted!==true||x.authenticated!==true||x.protectedKey!==true||typeof x.unlocked!=='boolean')throw Error('Secure vault unavailable');return x}function accounts(xs){if(!Array.isArray(xs)||xs.length>100)throw Error('Invalid accounts');const ids=new Set();for(const x of xs){if(!/^[A-Za-z0-9_-]{1,64}$/.test(x.id)||ids.has(x.id)||typeof x.label!=='string'||!x.label||x.label.length>120)throw Error('Invalid account');ids.add(x.id)}return xs.map(x=>({id:x.id,label:x.label}))}function code(x,now=Date.now()){if(!x||!/^\d{6}(?:\d{2})?$/.test(x.code)||!Number.isSafeInteger(x.validUntil)||x.validUntil<=now||x.validUntil>now+60000)throw Error('Expired or invalid code');return x}return{totp,capability,accounts,code}});
